with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'マダムXの肖像', 'ジョン・シンガー・サージェント', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Sargent_MadameX.jpeg/960px-Sargent_MadameX.jpeg', '1884年、パリの銀行家ピエール・ゴートローの妻ヴィルジニー・アメリー・ゴートローを描いた肖像画です。黒いドレスと白い肌の強い対比、横を向いた顔の輪郭が印象的です。同年のサロンでは、肩から滑り落ちた肩紐が品がないと批判され、サージェントは後に肩紐を描き直しました。作品はサージェントのアトリエに長く飾られ、1916年にメトロポリタン美術館が購入しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Sargent_MadameX.jpeg'),
    (2, '清明上河図', '張択端', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Alongtheriver_QingMing.jpg/960px-Alongtheriver_QingMing.jpg', '北宋の都・汴京（現在の開封とされる）の川沿いのにぎわいを、縦約25センチ、長さ5メートルを超える絹の巻物に描いた作品です。右の郊外から始まり、中央の虹橋では帆柱を倒しきれない船に人々が騒ぎ、左へ進むと店や宿が建ち並ぶ市街になります。800人を超える人物が描き込まれ、宋代の暮らしを伝えます。北京の故宮博物院所蔵。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Alongtheriver_QingMing.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('目［mé］《まさゆめ》、奥多摩の空に', '巨大な顔を空に浮かべる目［mé］の《まさゆめ》が、ARTE TOKYOの特別企画として5年ぶりに東京で展示された。', '現代アートチーム目［mé］（荒神明香、南川憲ニ、増井宏文）のプロジェクト《まさゆめ》が、東京都などが主催する「ARTE TOKYO」の特別企画として、11月21日・22日に東京・奥多摩町で展示された。荒神が14歳のときに見た「巨大な人の顔が月のように浮かんでいる夢」に着想し、世界中から集めた実在の人々の顔からひとりを選んで空に浮かべる作品。2021年に代々木公園などで初めて展示され、2023年にリスボン、2024年にマドリードでも実施された。奥多摩での実施は初めてで、12月5日・6日には代々木公園でも予定されている。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/report/33372',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「東京建築祭2027」開催決定、新宿が加わる', '東京の建築を舞台にした「東京建築祭」の2027年の開催が決まり、新たに新宿エリアが加わる。', '東京の多様な建築を舞台にした建築体験イベント「東京建築祭2027」の開催が決まった。会期は2027年5月15日〜23日の9日間で、特別公開日は22日・23日。2024年に始まり、3年目の2026年は150件の建築が参加し、延べ約16万5000人が来場した。2027年は約165件の参加を予定し、上野や丸の内、銀座、渋谷などに加えて、西新宿の超高層ビル群や歌舞伎町、ゴールデン街のある新宿エリアが新たな舞台となる。普段は入れない建築の特別公開のほか、ガイドツアーやトークイベントも行う。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33362',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('国立市に「Newtown Art Center」誕生', '東京・国立市に、ギャラリーやイベントに使える新しいアートスペース「Newtown Art Center」が生まれた。', '東京都国立市の国立中央ビル北館4階に、新しいアートスペース「Newtown Art Center（ニュータウンアートセンター）」が誕生した。かつて執務スペースだった約120坪の区画を転用した文化発信の拠点で、ギャラリーや小規模なイベントに対応する。中核となるギャラリーはアートアンドリーズン株式会社が運営し、2014年に恵比寿で開廊した「MASUMI SASAKI GALLERY」が移転した。11月7日から15日までのプレオープンでは、我喜屋位瑳務の「CHILLDIE Ⅸ -Preview」が開かれた。', '', '美術館', 'https://bijutsutecho.com/magazine/news/headline/33323',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('新千歳空港でメディア芸術展「PASSING BY」', '文化庁の事業の特別企画として、若手クリエイターのメディア芸術作品を新千歳空港の国際線到着コンコースで紹介する。', '文化庁「メディア芸術クリエイター育成支援事業」の特別企画「PASSING BY」が、11月19日から24日まで、新千歳空港国際線ターミナルビルの到着コンコースで開かれている。日本の若手クリエイターによるメディア芸術作品を、訪日外国人が出会える場で紹介する企画で、入場は無料。大原崇嘉、芹澤碧、田村育歩、堂園翔矢、森田崇文、山中千尋の6人が参加し、横幅10メートルを超えるLEDディスプレイでの映像インスタレーションや、磁性流体を使ったキネティック・インスタレーションなどが並ぶ。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33315',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('タイタンの杯', 'The Titan''s Goblet', 'トマス・コール', 'Thomas Cole',
        1833,
        (select slug from public.art_movements where slug = 'romanticism'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Cole%2C_Thomas_-_Der_Pokal_des_Riesen_-_hi_res_-_1833.JPG/960px-Cole%2C_Thomas_-_Der_Pokal_des_Riesen_-_hi_res_-_1833.JPG', 'ふつうの野山に、巨大な石の杯がそびえ立つ不思議な風景画です。杯の縁には草木が茂り、ギリシャ風の神殿やイタリア風の宮殿が建ち、杯の中の水面には小さな帆船が浮かびます。こぼれた水が落ちた地面にも草が生え、素朴な暮らしが見えます。巨人が残した遺物のようにも、世界樹のようにも読まれてきましたが、コールは説明を残していません。アメリカの風景を描いたハドソン・リヴァー派の祖が、ロマン主義の想像力で風景と文明の関係を寓話にした一枚です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Cole,_Thomas_-_Der_Pokal_des_Riesen_-_hi_res_-_1833.JPG')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
