values ('トルコのスルタンへ手紙を書くザポロージャ・コサック', 'Reply of the Zaporozhian Cossacks', 'イリヤ・レーピン', 'Ilya Repin',
        1891,
        (select slug from public.art_movements where slug = 'realism'),
