insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ゆれる炎のあるマグダラのマリア', 'Magdalene with the Smoking Flame', 'ジョルジュ・ド・ラ・トゥール', 'Georges de La Tour',
        1640,
        (select slug from public.art_movements where slug = 'baroque'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/La_Tour_-_La_Madeleine_%C3%A0_la_veilleuse_dite_La_Madeleine_Terff%2C_vers_1642_-_1644%2C_RF_1949_11.jpg/960px-La_Tour_-_La_Madeleine_%C3%A0_la_veilleuse_dite_La_Madeleine_Terff%2C_vers_1642_-_1644%2C_RF_1949_11.jpg', '罪を悔いるマグダラのマリアが、ほおづえをついてろうそくの炎を見つめています。膝には頭蓋骨が置かれ、机には本や十字架、縄の鞭が並びます。暗闇の中でひとつの炎だけが顔と体を照らし、静かな祈りと人生のはかなさを感じさせます。制作は1640年ごろとされ、ほぼ同じ構図の作品がロサンゼルス・カウンティ美術館にもあります。カラヴァッジョが広めた強い明暗をバロックから受け継ぎながら、ラ・トゥールは動きを抑えた簡潔な形で、瞑想的な夜の絵を生み出しました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:La_Tour_-_La_Madeleine_à_la_veilleuse_dite_La_Madeleine_Terff,_vers_1642_-_1644,_RF_1949_11.jpg')
