insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('黄公望', 'Huang Gongwang', '黄公望',
        1269, 1354, 'east_asia', array['song-yuan']::text[],
        '「富春山居図」で知られる、元末四大家のひとりの水墨画家。', '元の時代の中国の水墨画家です。蘇州常熟県に生まれ、両親を亡くしたのち黄家の養子になりました。科挙が不定期で南方の人に不利だったこともあり、40歳を過ぎて蘇州の役所の下級役人になりましたが、関わりのない事件に連座して職を失いました。その後は占い師や道士などとして暮らしました。

趙孟頫に認められて絵に打ち込み、50歳を過ぎてから本格的に画家として活動しました。倪瓚、呉鎮、王蒙とともに「元末四大家」に数えられ、四人の中で最も画風の幅が広いとされます。

晩年に杭州の富陽県へ移り住んで描いた「富春山居図」は、水墨山水画の代表的な傑作です。後の時代の文人画家への影響は、四大家の中でも最も大きいとされています。', 'https://ja.wikipedia.org/wiki/%E9%BB%84%E5%85%AC%E6%9C%9B')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アンゲリカ・カウフマン', 'Angelica Kauffman', 'カウフマン',
        1741, 1807, 'west', array['neoclassicism']::text[],
        'ロンドンとローマで活躍し、ロイヤル・アカデミーの創設会員となった新古典主義の画家。', 'スイスのクールに生まれ、オーストリアで育った画家です。父ヨーゼフ・ヨーハン・カウフマンも画家で、幼いころから才能を示し、12歳ごろには聖職者や貴族の肖像を描いて評判になりました。1754年に父とミラノへ行き、長くイタリアを旅して古典を学びました。

その後ロンドンに渡り、1768年に創設されたロイヤル・アカデミーの創設メンバーとなりました。創設会員の中で女性はカウフマンとメアリー・モーザーの二人だけでした。古代の歴史や神話、寓意を主題に、端正な線と落ち着いた構図で描く新古典主義の画家として知られます。

1781年に画家アントニオ・ズッキと結婚してローマへ移りました。代表作に『テレマコスの悲しみ』や『ヘレネにパリスを愛するよう説得するヴィーナス』があります。1807年にローマで亡くなり、彫刻家カノーヴァの指揮で盛大な葬儀が営まれました。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%B3%E3%82%B2%E3%83%AA%E3%82%AB%E3%83%BB%E3%82%AB%E3%82%A6%E3%83%95%E3%83%9E%E3%83%B3_(%E7%94%BB%E5%AE%B6)')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ポール・ナッシュ', 'Paul Nash', 'ナッシュ',
        1889, 1946, 'west', array['surrealism']::text[],
        '二つの世界大戦の戦争画家として、またシュルレアリスムに通じる風景画で知られるイギリスの画家。', 'ロンドンに生まれたイギリスの画家です。1910年からスレイド美術学校に約1年学びました。弟のジョン・ナッシュも画家です。

第一次世界大戦ではベルギーのイーペル周辺の前線に従軍し、負傷して帰国したのち、公式の戦争画家として戦場に戻りました。荒れ果てた大地を描いた『我々は新しい世界を創造している』（1918年）がよく知られています。初期は写実的な風景画が中心でしたが、のちに風景の中に幾何学的なオブジェを置くなど、謎めいた組み合わせを描くようになり、シュルレアリスムに近づきました。1933年にはユニット・ワンの結成に加わり、1936年のロンドン国際シュルレアリスム展にも出品しています。

第二次世界大戦でも戦争画家となり、撃墜された飛行機の残骸を海の波に見立てた『死の海（トーテス・メーア）』を描きました。1946年に亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%83%9D%E3%83%BC%E3%83%AB%E3%83%BB%E3%83%8A%E3%83%83%E3%82%B7%E3%83%A5')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
